import java.lang.reflect.Constructor;
import java.util.Scanner;

public class Main {
    static class 小猫 {
        int 编号;
        int {t};

        小猫(int 编号, int 根数) {
            this.编号 = 编号;
            this.{t} = 根数;
        }
    }

    public static void main(String[] args) throws Exception {
        Scanner sc = new Scanner(System.in);
        int 编号 = sc.nextInt();
        int 根数 = sc.nextInt();

        Constructor<?> 产房 = 小猫.class.getDeclaredConstructor(int.class, int.class);
        小猫 新的 = (小猫) 产房.newInstance(编号, 根数);
        System.out.println("第 " + 新的.编号 + " 号有 " + 新的.{t} + " 根{t}");
    }
}
